with open('Aurelian/app/src/main/java/com/aurelian/app/MainFeedScreen.kt', 'r') as f:
    content = f.read()
old_view = '        // Video Player Background with Fade-in Animation\n        AnimatedVisibility(\n            visible = isVideoReady,\n            enter = fadeIn(animationSpec = tween(700)),\n            exit = fadeOut()\n        ) {\n            AndroidView(\n                factory = { ctx ->\n                    PlayerView(ctx).apply {\n                        player = exoPlayer\n                        useController = false\n                        resizeMode = AspectRatioFrameLayout.RESIZE_MODE_ZOOM\n                        layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)\n                    }\n                },\n                modifier = Modifier.fillMaxSize()\n            )\n        }'
new_view = '        // Video Player Background with Fade-in Animation\n        AnimatedVisibility(\n            visible = isVideoReady,\n            enter = fadeIn(animationSpec = tween(700)),\n            exit = fadeOut()\n        ) {\n            exoPlayer?.let { player ->\n                AndroidView(\n                    factory = { ctx ->\n                        PlayerView(ctx).apply {\n                            this.player = player\n                            useController = false\n                            resizeMode = AspectRatioFrameLayout.RESIZE_MODE_ZOOM\n                            layoutParams = FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT)\n                        }\n                    },\n                    modifier = Modifier.fillMaxSize(),\n                    update = { view ->\n                        view.player = player\n                    }\n                )\n            }\n        }'
content = content.replace(old_view, new_view)
with open('Aurelian/app/src/main/java/com/aurelian/app/MainFeedScreen.kt', 'w') as f:
    f.write(content)
